package io.aetheris.orchestrator.trading;import org.springframework.stereotype.Service;import java.util.UUID;@Service public class Stage9PaperTradingService {private final MultiSourceMarketDataBook consensus;private final ManualMarketDataAdapter stage8Market;private final PaperTradingService paper;public Stage9PaperTradingService(MultiSourceMarketDataBook consensus,ManualMarketDataAdapter stage8Market,PaperTradingService paper){this.consensus=consensus;this.stage8Market=stage8Market;this.paper=paper;}public PaperExecutionResult openConsensus(UUID signalId,String symbol,int minSources,long maxAge,long maxSkew,double maxDiv){MarketConsensus c=consensus.consensus(symbol,minSources,maxAge,maxSkew,maxDiv);stage8Market.ingest(c.snapshot());return paper.open(signalId);}}
